import{_ as d,C as l,o as s,c as h,j as i,E as n,a as o,a3 as r}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"n":1,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":1,"title":"UX va UI dizayn tushunchalari: nima va nima uchun","lead":"Har kuni Telegram, Instagram yoki o'yinlarni ochasiz, lekin ularning ko'rinishi va qulayligi ortida kimdir turganini o'ylab ko'rganmisiz? Bugun siz ikkita sirli qisqartma, UX va UI, ni ajratishni o'rganasiz va ilovalarga dizayner ko'zi bilan qaraysiz.","link":"/mentor/9-sinf/hafta-01/dars-1","slide":"/slaydlar/9-sinf/hafta-01/dars-1.html","test":"/slaydlar/9-sinf/hafta-01/dars-1-test.html"},{"g":2,"title":"UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","lead":"Nega bir ilovani «o'zi tushunarli» deymiz, boshqasida esa adashib qolamiz? Bugun yaxshi dizaynni ajratadigan aniq qoidalarni (4C va 7 ta UX tamoyili) va dizayn qanday bosqichlardan o'tishini o'rganamiz.","link":"/mentor/9-sinf/hafta-01/dars-2","slide":"/slaydlar/9-sinf/hafta-01/dars-2.html","test":"/slaydlar/9-sinf/hafta-01/dars-2-test.html"},{"g":3,"title":"Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","lead":"Yaxshi dizayner chizishdan oldin so'raydi, kuzatadi va tinglaydi. Bugun siz sinfdoshingizdan haqiqiy intervyu olasiz va uning «portreti» (persona) ni yasaysiz.","link":"/mentor/9-sinf/hafta-01/dars-3","slide":"/slaydlar/9-sinf/hafta-01/dars-3.html","test":"/slaydlar/9-sinf/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf/hafta-01/index.md","filePath":"mentor/9-sinf/hafta-01/index.md"}`),e={name:"mentor/9-sinf/hafta-01/index.md"},u={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function m(q,a,v,k,f,c){const t=l("Icon");return s(),h("div",null,[i("div",u,[i("h2",y,[n(t,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki bitta hujjatda (Google Docs, Notes, Figma/Canva) saqlang; skrinshot va rasmlarni shu hujjatga qo&#39;shing. Topshirish: keyingi dars boshida mentorga ko&#39;rsating (daftar, hujjat yoki telefondagi rasm).</p><h2 id="_1-dars-uchun-ux-va-ui-tushunchalari" tabindex="-1">1-dars uchun (UX va UI tushunchalari) <a class="header-anchor" href="#_1-dars-uchun-ux-va-ui-tushunchalari" aria-label="Permalink to &quot;1-dars uchun (UX va UI tushunchalari)&quot;">​</a></h2><p><strong>1-topshiriq: «Mening ilovamda yaxshi va yomon UX»</strong> (20–25 daqiqa)</p><ol><li>O&#39;zingiz kunda foydalanadigan bitta ilovani tanlang (masalan, Telegram, Click, YouTube, maktab ilovasi).</li><li>Ilovani ochib, oddiy bitta ishni bajaring (xabar yuborish, to&#39;lov qilish, video topish) va jarayonni kuzating.</li><li>Bitta yaxshi UX nuqtasini toping: qaysi joyi sizga qulay yoki tushunarli?</li><li>Bitta yomon UX nuqtasini toping: qayerda to&#39;xtab qoldingiz, adashdingiz yoki asabiylashdingiz?</li><li>Har biri uchun skrinshot oling yoki 1–2 gapda tavsiflang va nega shunday ekanini bir jumlada yozing.</li><li>Oxirida bir gap yozing: bu nuqta UX ga (tajriba, qulaylik) tegishlimi yoki UI ga (ko&#39;rinish) tegishlimi?</li></ol><p><strong>Kutiladigan natija:</strong> bitta ilova, bitta yaxshi va bitta yomon nuqta, har birining sababi bir jumlada; UX va UI farqini ishlatgan holda yozilgan. <strong>Nimani topshirasiz:</strong> daftar yozuvi yoki hujjat (skrinshotlar bilan).</p><h2 id="_2-dars-uchun-ux-tamoyillari-va-dizayn-jarayoni" tabindex="-1">2-dars uchun (UX tamoyillari va dizayn jarayoni) <a class="header-anchor" href="#_2-dars-uchun-ux-tamoyillari-va-dizayn-jarayoni" aria-label="Permalink to &quot;2-dars uchun (UX tamoyillari va dizayn jarayoni)&quot;">​</a></h2><p><strong>2-topshiriq: «Uch ekranni 4C bo&#39;yicha baholash»</strong> (20–30 daqiqa)</p><ol><li>Bitta ilovani tanlang (1-vazifadagi bilan bir xil bo&#39;lishi shart emas).</li><li>Uning 3 ta ekranini tanlang (masalan, bosh sahifa, qidiruv, sozlamalar). Har biriga skrinshot oling yoki nomini yozing.</li><li>4C jadvalini tuzing: qatorlarda Control, Consistency, Comfortability, Cognitive Load; ustunlarda 3 ta ekran.</li><li>Har bir tamoyil uchun bitta aniq dalil yozing: ekranda aynan nima buni ko&#39;rsatadi? («Qulay» kabi umumiy gap yetarli emas.)</li><li>Har bir tamoyilga belgi qo&#39;ying: «yaxshi» yoki «buzilgan».</li><li>Bitta eng zaif joyni tanlab, uni qanday yaxshilash mumkinligini bir gapda taklif qiling.</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;ldirilgan 4C jadvali, har bir tamoyil uchun bitta dalil, bitta taklif. <strong>Nimani topshirasiz:</strong> jadvalning rasmi yoki hujjati (3 ekran skrinshoti bilan).</p><h2 id="_3-dars-uchun-foydalanuvchi-tadqiqotlari-i" tabindex="-1">3-dars uchun (Foydalanuvchi tadqiqotlari I) <a class="header-anchor" href="#_3-dars-uchun-foydalanuvchi-tadqiqotlari-i" aria-label="Permalink to &quot;3-dars uchun (Foydalanuvchi tadqiqotlari I)&quot;">​</a></h2><p><strong>3-topshiriq: «Intervyu va persona»</strong> (20–30 daqiqa)</p><ol><li>Sinfdoshdan farqli kamida 3 ta odam toping (oila a&#39;zosi, boshqa yoshdagi odam, qo&#39;shni).</li><li>Har biridan bitta ilova yoki xizmat (masalan, kitob izlash, to&#39;lov, taksi chaqirish) haqida 5 daqiqalik intervyu oling. 5 ta ochiq savol oldindan yozib qo&#39;ying (dars daftaridagi shablondan foydalaning).</li><li>Javoblarni yozib boring: savol, javob, qiziq iqtibos. Maslahat bermang, ko&#39;proq tinglang.</li><li>Yozuvlarni qayta o&#39;qing va takrorlanadigan odat, motivatsiya va og&#39;riq nuqtalarini belgilang.</li><li>Shundan bitta persona kartasini tuzing: xayoliy ism va yosh, odat, motivatsiya, og&#39;riq nuqtasi, maqsad va bitta iqtibos.</li><li>Kartadagi har bir band intervyudagi qaysi javobdan kelib chiqqanini yonida qisqa yozing.</li></ol><p><strong>Kutiladigan natija:</strong> 3 ta intervyuning yozuvi va bitta persona kartasi; karta o&#39;ylab topilmagan, intervyudagi faktlarga asoslangan. <strong>Nimani topshirasiz:</strong> daftardagi yozuv va kartaning rasmi (skrinshot yoki foto). Keyingi darsda shu kartadan ssenariy yozamiz.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p><strong>Qanday ko&#39;rib chiqish.</strong> Keyingi dars boshida (takrorlash, ~10 daqiqa) 1–2 ta ishni ekranda ko&#39;rib chiqing; xatoni o&#39;zi topishga undang («Bu dalil qaysi tamoyilni isbotlaydi?»). Ishni topshirgan/topshirmaganini baholash jadvaliga yozing.</p><p><strong>1-topshiriq: odatiy xatolar.</strong></p><ul><li>«Chiroyli» yoki «yoqmaydi» kabi sababsiz fikr; sababni so&#39;rang.</li><li>UI (rang, shrift) ni UX (qulaylik, jarayon) bilan aralashtirish.</li><li>Ilovani ishlatmasdan, xotiradan yozish.</li></ul><p><strong>2-topshiriq: odatiy xatolar.</strong></p><ul><li>Dalil o&#39;rniga umumiy gap («qulay ekan»); aniq element va ekranni so&#39;rang.</li><li>Cognitive Load va Comfortability ni aralashtirish (birinchisi ma&#39;lumot ko&#39;pligi, ikkinchisi qo&#39;l/ko&#39;z uchun qulaylik).</li><li>Hamma tamoyil «yaxshi» deb baholanadi; ilovada kamida bitta zaif joy topiladi, qidirishni so&#39;rang.</li><li>Bir xil ekranni 3 marta tanlash. Boshqa ilova tanlansa, mantiqiy dalil bo&#39;lsa qabul qiling.</li></ul><p><strong>3-topshiriq: odatiy xatolar.</strong></p><ul><li>Yopiq savollar («ha/yo&#39;q»), yetaklovchi savollar.</li><li>Sinfdoshlarni so&#39;rash yoki 3 dan kam odam bilan suhbat.</li><li>Persona o&#39;ylab topilgan: «hamma uchun qulay» kabi umumiy bandlar, intervyuda aytilmagan gaplar.</li><li>Personada ssenariy yoki journey map yozib yuborish: bular 4-darsning mavzusi.</li></ul><p><strong>Muddat va qo&#39;llab-quvvatlash.</strong> Topshirmagan o&#39;quvchiga keyingi darsda 10 daqiqa ajrating; 3-vazifa uchun intervyu odam topa olmasa, oila a&#39;zosidan boshlashni maslahat bering.</p>',22))]),i("div",g,[i("h2",b,[n(t,{name:"list-checks"}),a[3]||(a[3]=o(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Shkala haqida.</strong> 9-sinf o&#39;quv materiallarida (<code>9-sinf/_matn/</code>) o&#39;quvchini baholash shkalasi berilmagan: faqat foydalanuvchi testlarining ko&#39;rsatkichlari (bajarish vaqti, bosishlar soni, qoniqish darajasi) aytilgan, ular o&#39;quvchi bahosi emas. Shu sababli 8-sinfdagi umumiy 100 ballik shkala qo&#39;llanadi (mentor o&#39;zgartirishi mumkin): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Guruhdagi o&#39;quvchilar soni noma&#39;lum, shuning uchun har jadvalda 3 ta bo&#39;sh qator; kerak bo&#39;lsa qatorlarni qo&#39;shing.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mavzu mohiyatini tushunadi va aytib bera oladi (tezkor nazorat)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq bajarilgan</td><td>30</td></tr><tr><td>Dalil va tahlil: fikr aniq misol bilan asoslangan, atamalar to&#39;g&#39;ri</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><p>Qo&#39;shimcha: mustaqil fikrlash, qiyin yoki bonus topshiriqni bajarish, guruhda faol qatnashish baholashda e&#39;tiborga olinadi.</p><h2 id="_1-dars-ux-va-ui-tushunchalari" tabindex="-1">1-dars (UX va UI tushunchalari) <a class="header-anchor" href="#_1-dars-ux-va-ui-tushunchalari" aria-label="Permalink to &quot;1-dars (UX va UI tushunchalari)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: UX va UI farqini to&#39;g&#39;ri ajratish. Uyga vazifa: bitta yaxshi va bitta yomon UX nuqtasi, sabablari bilan.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dalil va tahlil /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_2-dars-ux-tamoyillari-va-jarayon" tabindex="-1">2-dars (UX tamoyillari va jarayon) <a class="header-anchor" href="#_2-dars-ux-tamoyillari-va-jarayon" aria-label="Permalink to &quot;2-dars (UX tamoyillari va jarayon)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: 4C va UX tamoyillarini ekranda topish; wireframe, mockup va prototip farqi. Uyga vazifa: 3 ekranni 4C bo&#39;yicha baholash (har tamoyilga bitta dalil).</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dalil va tahlil /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="_3-dars-foydalanuvchi-tadqiqotlari-i" tabindex="-1">3-dars (Foydalanuvchi tadqiqotlari I) <a class="header-anchor" href="#_3-dars-foydalanuvchi-tadqiqotlari-i" aria-label="Permalink to &quot;3-dars (Foydalanuvchi tadqiqotlari I)&quot;">​</a></h2><p>Amaliyotda e&#39;tibor: tadqiqot usullarini ajratish, ochiq savol tuzish, mini-intervyu va persona kartasi (dalil va tahlil: karta intervyuga asoslanganmi). Uyga vazifa: 3 ta intervyu va bitta persona kartasi.</p><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>Tezkor nazorat /30</th><th>Amaliyot /30</th><th>Dalil va tahlil /20</th><th>Uyga vazifa /20</th><th>Jami</th><th>Baho</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-yakuni" tabindex="-1">Hafta yakuni <a class="header-anchor" href="#hafta-yakuni" aria-label="Permalink to &quot;Hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th>1-dars</th><th>2-dars</th><th>3-dars</th><th>O&#39;rtacha</th><th>Baho</th><th>Izoh (kuchli/zaif tomonlari)</th></tr></thead><tbody><tr><td>1.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3.</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><h2 id="hafta-xulosasi-va-keyingi-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi haftaga ko&#39;prik&quot;">​</a></h2><p><strong>Bu hafta:</strong> UX va UI farqi; UI ning 4C tamoyili, UX tamoyillari, yaxshi va yomon dizayn belgilari; dizayn jarayoni (wireframe, mockup, prototip); tadqiqot usullari (so&#39;rovnoma, intervyu, kuzatuv, fokus guruh, testlash, ma&#39;lumot tahlili), persona.</p><p><strong>Keyingi hafta (2-hafta, 4-dars):</strong> «Foydalanuvchi tadqiqotlari» davom etadi: bugungi persona kartasi asosida ssenariy yoziladi, so&#39;ng foydalanuvchi oqimi (user flow) va journey map tuziladi. Shu sababli 3-darsdagi persona kartasi sifati muhim: kartasi zaif o&#39;quvchilarga 4-dars boshida intervyu yozuvlarini qayta ko&#39;rib chiqishga 5–10 daqiqa bering.</p><p>Oraliq yoki yakuniy nazorat bu haftaga to&#39;g&#39;ri kelmaydi.</p>',20))])])}const x=d(e,[["render",m]]);export{p as __pageData,x as default};
